// ============================================================================
// CORTEX // Pre-Baked 240Hz Zero-Phase + Sliding-Window P95 Audio Envelopes
// Generated from `assets/version_b_master.mp3` @ 48000Hz (exact 200 samples/bin, zero drift).
// Exposes `window.CORTEX_AUDIO_ENV_240HZ`:
//   { hz: 240, length: 67596, kickPulse, snareSnap, arp16Tick, vocalGate, whipPre }
// ============================================================================
(function () {
  'use strict';
  const N = 67596;
  function dec(b64) {
    const bin = atob(b64);
    const out = new Float32Array(bin.length);
    const inv = 1 / 255;
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i) * inv;
    return out;
  }
  const kickPulse = dec("");
  const snareSnap = dec("");
  const arp16Tick = dec("");
  const vocalGate = dec("");
  const whipPre   = dec("");

  window.CORTEX_AUDIO_ENV_240HZ = {
    hz: 240,
    length: N,
    kickPulse,
    snareSnap,
    arp16Tick,
    vocalGate,
    whipPre,
    kick: kickPulse,
    snare: snareSnap,
    arp16: arp16Tick,
    vocal: vocalGate
  };
})();
